item.aggregated_output:
'use strict';

// Herdr's socket API, for the writes the CLI wrapper makes too slow.
//
// Every `herdr` CLI call is a process spawn — 40-80ms on Windows — and the
// animator writes tokens per pane, so a mode flip that repaints thirty panes
// crawled through seconds of serial spawns while the sidebar visibly walked
// into place. The socket takes the same requests as newline-delimited JSON;
// the server answers one request per connection and hangs up, so calls are
// parallel by construction. A small in-flight cap keeps a full repaint from
// opening seventy pipes at once.

const net = require('node:net');
const path = require('node:path');

const { herdrConfigPath } = require('./paths');

const TIMEOUT_MS = 4000;
const MAX_IN_FLIGHT = 16;

function pipePath() {
  const sock = process.env.HERDR_SOCKET_PATH ?? path.join(path.dirname(herdrConfigPath()), 'herdr.sock');
  // Herdr's Windows listener registers the whole path string as a named pipe.
  return process.platform === 'win32' ? `\\\\.\\pipe\\${sock}` : sock;
}

function rawCall(method, params) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      stream.destroy();
      resolve(value);
    };
    const stream = net.connect({ path: pipePath() });
    let body = '';
    stream.setTimeout(TIMEOUT_MS, () => finish(null));
    stream.on('error', () => finish(null));
    stream.on('connect', () => stream.write(`${JSON.stringify({ id: 'plugin-ipc', method, params })}\n`));
    stream.on('data', (chunk) => {
      body += chunk;
      const line = body.indexOf('\n');
      if (line < 0) return;
      try {
        finish(JSON.parse(body.slice(0, line)));
      } catch {
        finish(null);
      }
    });
  });
}

let inFlight = 0;
const waiters = [];

// The parsed reply, or null on any transport failure. A reply with an
// `error` field is still returned — the caller decides what a refusal means.
async function call(method, params) {
  if (inFlight >= MAX_IN_FLIGHT) await new Promise((wake) => waiters.push(wake));
  inFlight += 1;
  try {
    return await rawCall(method, params);
  } finally {
    inFlight -= 1;
    waiters.shift()?.();
  }
}

module.exports = { call };

function panelGrouped(now = Date.now()) {
  if (now - sortCache.at < 2000) return sortCache.grouped;
  let grouped = true;
  try {
    const mode = fs.readFileSync(herdrConfigPath(), 'utf8').match(/^\s*agent_panel_sort\s*=\s*"([^"]+)"/m)?.[1];
    grouped = mode !== 'priority';
  } catch {
    // An unreadable config reads as Herdr's default, which is grouped.
  }
  Object.assign(sortCache, { at: now, grouped });
  return grouped;
}

function workspaceGet(workspaceId) {
  if (!workspaceId) return null;
  return call('workspace', 'get', workspaceId)?.result?.workspace ?? null;
}

// Set and clear display tokens in one call. `tokens` maps name -> value, where
// null or undefined means "clear this one".
//
// Clearing matters as much as setting: this plugin encodes state in *which*
// token is present (one colour per token name, since Herdr's row styles are
// static), so a stale name left behind renders beside the current one.
function reportMetadata(paneId, source, tokens) {
  const args = ['pane', 'report-metadata', paneId, '--source', source];
  for (const [name, value] of Object.entries(tokens)) {
    if (value === null || value === undefined) args.push('--clear-token', name);
    else args.push('--token', `${name}=${value}`);
  }
  return call(...args) !== null;
}

// Workspace-level twin of reportMetadata, for tokens the Spaces list renders.
function reportWorkspaceMetadata(workspaceId, source, tokens) {
  const args = ['workspace', 'report-metadata', workspaceId, '--source', source];
  for (const [name, value] of Object.entries(tokens)) {
    if (value === null || value === undefined) args.push('--clear-token', name);
    else args.push('--token', `${name}=${value}`);
  }
  return call(...args) !== null;
}

// The socket API's token patch: name -> value, null meaning clear — the same
// contract the CLI flags encode, minus the process spawn.
function tokenPatch(tokens) {
  const patch = {};
  for (const [name, value] of Object.entries(tokens)) patch[name] = value ?? null;
  return patch;
}

// Async twins of the two report calls, over the socket. The CLI wrapper costs
// a process spawn per write — 40-80ms on Windows — which turns any repaint
// touching every pane into seconds of visible catching-up. Socket calls run
// in parallel; a transport failure falls back to one CLI attempt so a machine
// where the socket misbehaves degrades to slow, not broken.
//
// A report to a pane or workspace that no longer exists is DONE, not failed.
// Herdr answers it with a not-found error, and that answer is final: the
// target is gone, and its tokens went with it. Reporting it as a failure put
// the target into the frame's retry backoff, which caps at a minute and never
// gives up — so every pane and workspace that ever closed was cleared again
// once a minute for the daemon's whole life, most of its IPC calls ended in
// errors, and each pending retry kept waking the scheduler (#21).
const GONE = new Set(['pane_not_found', 'workspace_not_found']);
const landed = (reply) => !reply.error || GONE.has(reply.error.code);

async function reportMetadataAsync(paneId, source, tokens) {
  const reply = await ipc.call('pane.report_metadata', {
    pane_id: paneId,
    source,
    tokens: tokenPatch(tokens),
  });
  if (reply) return landed(reply);
  return reportMetadata(paneId, source, tokens);
}

async function reportWorkspaceMetadataAsync(workspaceId, source, tokens) {
  const reply = await ipc.call('workspace.report_metadata', {
    workspace_id: workspaceId,
    source,
    tokens: tokenPatch(tokens),
  });
  if (reply) return landed(reply);
  return reportWorkspaceMetadata(workspaceId, source, tokens);
}

module.exports = {
  pluginId,
  source,
  reloadConfig,
  configCheck,
  notify,
  call,
  panes,
  pane,
  paneProcessCwd,
  tabRowWidth,
  agents,
  tabs,
  workspaces,
  workspaceGet,
  agentsAsync,
  workspacesAsync,
  tabsAsync,
  panesAsync,
  panelGrouped,
  reportMetadata,
  reportWorkspaceMetadata,
  reportMetadataAsync,
  reportWorkspaceMetadataAsync,
  binary,
};
// is 21, so every write here goes out in chunks.
const MAX_TOKENS_PER_REPORT = 16;

// Split a token set across as many reports as the cap needs. `report` is the
// call that carries one patch — panes and workspaces have their own, and both
// answer to the same ceiling.
function reportChunked(report, target, source, tokens) {
  const names = Object.keys(tokens);
  const chunks = [];
  for (let at = 0; at < names.length; at += MAX_TOKENS_PER_REPORT) {
    const patch = {};
    for (const name of names.slice(at, at + MAX_TOKENS_PER_REPORT)) patch[name] = tokens[name];
    chunks.push(report(target, source, patch));
  }
  return Promise.all(chunks).then((results) => results.every(Boolean));
}

function reportPane(source, pane, tokens) {
  return reportChunked(herdr.reportMetadataAsync, pane, source, tokens);
}

// Four token families, every one keyed by state: vendor logo, vendor name,
// state mark, title. Keying all four — not just the mark — is what lets a
// stale session recede as a WHOLE: logo, name and title fade together rather
// than the logo sitting there in full brand colour, which is an entry's
// loudest ink. Only one member of a family is ever set, so a row holding
// whole families still renders one cell per family.
// `working` publishes its logo under one of TWO names, alternating with the
// caller's `pulse` phase. The row config paints one plainly and the other
// with `dim`, so the mark breathes in its own brand colour — and it breathes
// by way of the terminal's dim rendering, which blends toward whatever is
// actually behind the panel. A hand-picked darker hex cannot: the direction
// that reads as "faded" flips between a light and a dark panel, and neither
// knows about a wallpaper showing through.
// The tokens a pane should be carrying for this frame, as a plain map. Split
// out from the write so a caller can compare it with what it sent last time:
// a frame of the working animation changes exactly two of these thirty-odd
// entries, and sending the other twenty-eight again costs a round trip Herdr
// answers in its own time — at four working panes that was fifty writes a
// second, which the server met with rising latency until the animation
// stuttered.
function stateTokens(display, line, title) {
  const tokens = {};
  // One logo, under whichever name carries the style this frame needs. The
  // other three are cleared: which name holds the glyph is the whole signal.
  for (const name of LOGO_TOKENS) tokens[name] = null;
  tokens[SPLIT_TOKEN] = line.split || null;
  if (line.logo) {
    const name = display === 'working' ? 'logo_working' : display === 'idle_stale' ? 'logo_stale' : 'logo';
    tokens[name] = line.logo;
  }
  // local patch: model mark, greyed with the row when stale.
  tokens.model = line.model && display !== 'idle_stale' ? line.model : null;
  tokens.model_stale = line.model && display === 'idle_stale' ? line.model : null;
  tokens.host = line.host;
  for (const state of STATES) {
    const current = state === display;
    // The vendor's name is gone from the layout; keep nulling its old token
    // so a pane that has one from a previous version loses it.
    tokens[`name_${state}`] = null;
    tokens[`state_${state}`] = current ? line.mark : null;
    tokens[`title_${state}`] = current && title ? line.titlePrefix + title : null;
  }
  return tokens;
}

// Only what differs from `sent`. Null means clear, and a key that was already
// null is not worth clearing again.
function tokenDelta(tokens, sent) {
  const delta = {};
  for (const [name, value] of Object.entries(tokens)) {
    if ((sent?.[name] ?? null) !== (value ?? null)) delta[name] = value;
  }
  return delta;
}

function writeTokens(source, pane, tokens) {
  return reportPane(source, pane, tokens);
}

function clearState(source, pane) {
  const tokens = { sort_key: null, ws_key: null, tab_key: null, [SPLIT_TOKEN]: null };
  for (const name of LOGO_TOKENS) tokens[name] = null;
  for (const state of STATES) {
    tokens[`name_${state}`] = null;
    tokens[`state_${state}`] = null;
    tokens[`title_${state}`] = null;
  }
  return reportPane(source, pane, tokens);
}

// The first pane of each workspace carries the name; the last carries a spacer.
// Herdr's Agents list has no group headers of its own — `agent_panel_sort =
// "spaces"` only orders entries — so a workspace with three tabs otherwise
// renders as three unrelated rows that each repeat the workspace name.
function groupBoundaries(entries) {
  // Walk them in the order Herdr gave us, which is the order the sidebar draws.
  // Sorting by pane id here looked equivalent and was not: ids are handed out
  // as p1..p9 then pA.., while the list follows layout, so a workspace ending
  // pN, pM, pK put the spacer on pN — three rows above the actual end, opening
  // a blank line through the middle of a group.
        gap: null,
      }),
    ),
  );
  return { heads: new Set(), ok: results.every(Boolean) };
}

// Every pane token the state path owns. `harness_logo` is deliberately not
// here: agent-icons.js writes it and manages its own lifecycle.
const OWNED_TOKENS = [
  'lane',
  'group',
  'group_parent',
  'group_stale',
  'gap',
  'sort_key',
  'ws_key',
  'tab_key',
  SPLIT_TOKEN,
  ...LOGO_TOKENS,
  ...STATES.map((s) => `name_${s}`),
  ...STATES.map((s) => `state_${s}`),
  ...STATES.map((s) => `title_${s}`),
];

// Clear our tokens from panes that are not in `live` but still carry them.
// The animator's own cleanup only covers panes it wrote itself — its record is
// in-memory — so a token written by an earlier animator, on a pane whose agent
// exited while no animator ran, outlives every writer. A leftover `group` is a
// duplicate workspace header in the sidebar. Only our source is touched: the
// clear is a no-op for a same-named token some other plugin set.
async function sweepOrphans(source, live, names = OWNED_TOKENS) {
  const jobs = [];
  for (const pane of await herdr.panesAsync()) {
    const id = pane.pane_id;
    if (typeof id !== 'string' || live.has(id)) continue;
    const tokens = pane.tokens && typeof pane.tokens === 'object' ? pane.tokens : {};
    if (!names.some((name) => name in tokens)) continue;
    const clear = {};
    for (const name of names) clear[name] = null;
    jobs.push(reportPane(source, id, clear)); // 25 owned names, 16 per report
  }
  return (await Promise.all(jobs)).every(Boolean);
}

/* ------------------------------------------------- workspace (Spaces) marks */

// The Spaces list gets the same glyph language as the agent rows: one mark per
// workspace, aggregated over its live agents. Colour is per token name, so
// `working` splits by vendor to keep the brand-colour scheme; every other
// state has one semantic token. A workspace with no live agent shows a
// neutral dot so its name stays aligned with the marked ones.
const SPACE_TOKENS = [
  'space_blocked',
  // Per branded vendor, from the palette's roster — the sidebar block builds
  // its cells from the same list, and a token with no cell is a mark that
  // never draws.
  ...palette.brandVendors.map((vendor) => `space_working_${vendor}`),
  'space_working_other',
  'space_done',
  'space_idle',
  'space_unknown',
  'space_none',
  // Not states: the vendors alive in the workspace, as logo + name on their
  // own row. One token per vendor, so each keeps its brand colour — Herdr
  // separates the cells with `·`, which on a row of its own reads as a divider
  // rather than clutter. Packing them into a single cell would buy back those
  // few columns at the cost of painting every vendor the same grey.
  ...palette.brandVendors.map((vendor) => `space_logo_${vendor}`),
  'space_logo_other',
  // The workspace name; see writeSpaceState for why it is published at all.
  'space_label',
];

// Which agent a workspace's single mark speaks for: a question beats activity
// beats an unseen result beats parked, and among parked ones the freshest.
//
// This must name every display a pane can carry. It used to list five of the
// seven, written before idle was split by freshness, and the two tiers it
// missed matched nothing — a workspace holding only fresh or only stale agents
// fell through to `none` and drew the empty-workspace dot. Since `idle_fresh`
// silent from the sidebar's side: the Spaces marks simply stop appearing.
function writeSpaceState(source, workspaceId, tokenName, glyph, logoTokens = {}, label = null) {
  const tokens = {};
  for (const name of SPACE_TOKENS) tokens[name] = name === tokenName ? glyph : null;
  Object.assign(tokens, logoTokens);
  // The Spaces panel's name column. Herdr's built-in `workspace` cell always
  // draws the real label and a plugin cannot style it; publishing the label as
  // a token of our own puts the whole row under the managed sidebar block, so
  // it takes the same colour rules as everything else there.
  tokens.space_label = label;
  return reportChunked(herdr.reportWorkspaceMetadataAsync, workspaceId, source, tokens);
}

function clearSpaceState(source, workspaceId) {
  const tokens = {};
  for (const name of SPACE_TOKENS) tokens[name] = null;
  return reportChunked(herdr.reportWorkspaceMetadataAsync, workspaceId, source, tokens);
}

// Everything this plugin painted, on every pane and workspace — the stop path.
// Two families stay: the title tokens, which the sidebar rows show the title
// THROUGH (clearing them blanks every entry, and a stopped plugin should leave
// a plain readable list, not an empty one), and the sort keys, which a view
// may still be ordering by (a frozen order beats a collapsed one). `purge`
// takes those too, plus the vendor logo agent-icons.js writes: the uninstall
// path, where the blocks that render them are about to go.
async function clearAll(source, { purge = false } = {}) {
  const names = purge
    ? [...OWNED_TOKENS, 'harness_logo']
    : OWNED_TOKENS.filter((name) => !name.startsWith('title_') && name !== 'sort_key' && name !== 'ws_key');
  await sweepOrphans(source, new Set(), names);
  await Promise.all(
    (await herdr.workspacesAsync())
      .filter((ws) => typeof ws.workspace_id === 'string')
      .map((ws) => clearSpaceState(source, ws.workspace_id)),
  );
}

module.exports = {
  clearAll,
  stateTokens,
  tokenDelta,
  writeTokens,
  STATES,
  LOGO_TOKENS,
  LEGACY_LOGO_TOKENS,
  baseState,
  SPACE_TOKENS,
  SPACE_PRIORITY,
  spaceToken,
  // Pure, and exported for tools/check.js: the row's name is decided here, and
  // the invariant that a vendor we can name never goes nameless has to run the
  // real pair rather than a copy of the stripping regex.
  stripVendorPulse,
  vendorTitle,
  INDENT,
  CHILD_INDENT,
  SPLIT_INDENT,
  INDENTS,
  LOCK,
  STOP,
  STALLED_MS,
  HUNG_FRAME_MS,
  daemonStatus,
  waitForExit,
  terminate,
  snapshot,
  labels,
  composeLine,
  clearState,
  spaceMark,
  spaceLogoTokens,
  writeSpaceState,
  clearSpaceState,
  groupBoundaries,
  trimGroupPrefix,
  writeGroups,
  clearGroups,
  sweepOrphans,
  OWNED_TOKENS,
};
    // left every member wearing the fallback colour.
    .map(([vendor, fg]) => `{ contains = "${glyphs[vendor]}", fg = "${fg}" }`);
  // The cell's own `fg` is the ink, and every rule above overrides it. So a
  // vendor with a hue wears it and everything else — a brand that signs in
  // black, an agent we have no mark for — is drawn in plain ink rather than in
  // a colour we made up for it. Leaving `fg` out instead, which is what this
  // did first, hands the mark Herdr's contextual default: a second-rank grey
  // that made those marks read as switched off (palette's `inkFor`).
  const base = `token = "${token}", fg = "${ink}", bold = ${bold}, dim = ${dim}`;
  return rules.length ? `{ ${base}, rules = [${rules.join(', ')}] }` : `{ ${base} }`;
}

// Which glyph table the rules above were written against. The rules match
// literal strings, so a block written for the icon font means nothing once the
// variant flips to plain Unicode — the daemon compares this line with what it
// resolves and rewrites the block when they disagree (lib/daemon.js).
const VARIANT_TAG = '# logo glyphs: ';

function blockVariant(text) {
  return new RegExp(`^${escapeRegExp(VARIANT_TAG)}(\\w+)$`, 'm').exec(text ?? '')?.[1] ?? null;
}

// Both sidebar lists, built from the same palette.
//
// Agents: the whole line (state mark + logo + name) is one token per state,
// because Herdr joins adjacent cells with `·` and one token means one colour —
// which is what carries the state here. The title row plays the same trick
// with the `$title_*` tokens so it dims and brightens with its state line —
// the built-in `terminal_title_stripped` cell could only ever be one static
// colour, which left a stale session's title as loud as a fresh one's.
// Titles stay unbolded even where the state line bolds: the mark line is a
// glyph, the title is prose. Spaces: the state mark and the vendor logos are
// separate cells so each can be coloured, and every extra cell costs a
// separator, so a Space running two or more vendors packs its logos into one.
// The freshness colours flip direction with the appearance, so the block is
// built per variant and rewritten by applyAppearance whenever the desktop
// flips — the same path that already rewrites the theme block.
function sidebarBlock(variant) {
  const brand = palette.brand;
  const ink = palette.inkFor(variant);
  const state = palette.stateFor(variant);
  // An entry is ONE row: `logo · title`. The vendor's name said what its
  // logo already said, and a state mark said what the title's colour now
  // says — two rows per session bought sixty rows for thirty sessions and no
  // information the first row lacked. The middot between the cells is Herdr's
  // own separator, unsuppressible, and here it falls between a mark and a
  // sentence, which is what a divider is for.
  //
  // Colour splits the same way: the logo is the vendor (its brand colour,
  // breathing while that session works), the title is the state (the
  // freshness scale, or a lifecycle colour when something needs you).
  const glyphs = logos.glyphs();
  const agentRow = (vendor) =>
    [
      // A synthesised parent for a worktree whose own checkout has no session
      // on the list — without it there is no pane to hang that name on and the
      // tree cannot stand up (lib/state.js writeGroups). Empty on every other
      // entry, where the row collapses. Second-rank on purpose: it names a repo
      // that has nothing running, so it should not read as loud as a live group.
      // The palette's stale tier says that now; the terminal's `dim` used to be
      // asked for as well, and on a dark panel that took the row out of reach.
      `[${[cell('$group_parent', state.idleStale, true)].join(', ')}]`,
      // The header fades with its workspace. When every session inside has
      // gone stale the name goes with them; leaving it at full strength put a
      // column of bright names over faded contents, which reads as damage
      // rather than as a project that is simply asleep.
      `[${[cell('$group', state.subtle, true), cell('$group_stale', state.idleStale, true)].join(', ')}]`,
      `[${[
        // Four names for one glyph, because these three styles are not in the
        // value and a rule can only read the value. Working breathes: the
        // daemon alternates the two `working` names and the only difference is
        // `dim`. Using the terminal's own dim rather than a darker hex means
        // the pulse blends toward whatever is actually behind the panel — a
        // hand-picked colour cannot, since the direction that reads as faded
        // flips between a light and a dark theme, and neither knows about a
        // wallpaper showing through. A stale row's logo leaves the brand
        // behind entirely and greys out with everything else in the row.
        // Structure, not content: the same grey a stale group header wears, so
        // the corner holds the row without competing with it.
        cell('$split_mark', state.idleStale),
        logoCell('$logo', glyphs, ink),
        // Deliberately the same style as `$logo`, bold included. Working used
        // to be the same glyph set bolder, which works for a letter and not
        // for a mark: the icon font ships one weight, so bold is SYNTHESISED
        // by dilating the outline — the glyph does not thicken, it grows. A
        // logo that changes size the moment a session stops working reads as a
        // rendering fault, and it is the first thing the eye catches in a
        // column of thirty. Working is already said three ways beside it: the
        // spinner in front of the title, the ring, and the title in the
        // vendor's colour. The two tokens stay apart because which NAME holds
        // the glyph is how a row's state is written (lib/state.js), not
        // because they have to look different.
        logoCell('$logo_working', glyphs, ink),
        cell('$logo_stale', state.idleStale),
        // local patch (2026-09-27): model family mark beside the harness logo.
        logoCell('$model', glyphs, ink),
        cell('$model_stale', state.idleStale),
        // A working title wears its vendor's colour. One shared warm colour
        // was tried instead — the brand is on the glyph beside it anyway — and
        // it flattened the panel: with thirty rows the hue is what tells one
        // running session from the next before any of them is read. That costs
        // a copy of this row per vendor below, since a value rule can read a
        // glyph but not a sentence. Working is also the one title that bolds:
        // a panel this long is scanned, and weight answers "which of these is
        // still going?" before colour does.
        cell('$title_working', brand[vendor] ?? brand.other, true),
        cell('$title_done', state.done),
        cell('$title_blocked', state.blocked),
        cell('$title_idle_fresh', state.idleFresh),
        cell('$title_idle', state.idleNormal),
        // `dim` used to carry this and cannot. It is a switch, not a value: it
        // asks the terminal to draw faintly and every terminal answers
        // differently — a third of the way to the background here, half there,
        // nothing elsewhere. An ink faint enough to survive the deepest of
        // those answers is too faint to read before any of them. The fade is
        // in the colour now, where it is ours and can be measured.
        cell('$title_idle_stale', state.idleStale),
        cell('$title_unknown', state.unknown),
      ].join(', ')}]`,
      // local patch (2026-09-27): machine name under the status mark (lib/state.js hostLine).
      `[${cell('$host', state.idleStale)}]`,
      '["$gap"]',
    ].join(', ');

  // Herdr rejects a row with more than 16 tokens — and rejects the whole
  // config file with it, which takes every plugin down. Cheaper to find out
  // here: this is generated, so the count moves whenever the palette does.
  for (const row of topLevelRows(agentRow('other'))) {
    const count = tokensIn(row);
    if (count > ROW_TOKEN_LIMIT) {
      throw new Error(`sidebar row would carry ${count} tokens; Herdr allows ${ROW_TOKEN_LIMIT}`);
    }
  }

  // Row one is the state mark and the name, and nothing else: the Spaces column
  // is narrow, and anything sharing that row truncates the very name it is
  // there to show. Row two carries the vendor logos, where Herdr's hanging
  // indent puts them under the name. The branch and its ahead/behind count used
  // to sit there — but a Space is picked by what is running in it, not by which
  // branch it happens to be on, and the agents were the thing with nowhere left
  // to go.
  // A named working mark per branded vendor; everything else shares `other`.
  // The roster used to be kept short because a workspace wrote its whole token
  // set in one patch and Herdr rejects a patch over sixteen tokens whole — that
  // is chunked now (lib/state.js), so the list can simply follow the palette.
  const spaceMarks = [
    cell('$space_blocked', state.blocked, true),
    // One working mark per branded vendor, straight off the palette's roster,
    // so a vendor added there is coloured in both panels or in neither.
    ...palette.brandVendors.map((vendor) => cell(`$space_working_${vendor}`, brand[vendor], true)),
    cell('$space_working_other', brand.other, true),
    cell('$space_done', state.done, true),
    cell('$space_idle', state.idle),
    cell('$space_unknown', state.unknown),
    cell('$space_none', state.none),
    // The workspace name is a token we publish rather than Herdr's built-in
    // `workspace` cell, so the whole Spaces row is under the plugin's control
    // (colour today; anything rendered into the label tomorrow).
    cell('$space_label', state.none),
  ];
  const spaceLogos = [
  const broken = checkedWrite(report.file, next, backup(report.file));
  if (broken) return { ok: false, changed: false, message: broken };
  return { ok: true, changed: true, message: `herdr: sidebar rows ${on ? 'on' : 'off'}` };
}

function remove() {
  const report = inspect();
  if (!report.text) return { ok: false, message: `herdr: nothing to remove (${report.state})` };
  backup(report.file);
  let next = dropBlock(report.text, BLOCK_START, BLOCK_END);
  next = dropBlock(next, THEME_START, THEME_END);
  next = dropBlock(next, SIDEBAR_START, SIDEBAR_END);
  next = restoreThemeOrigin(next);
  writeAtomic(report.file, next, identity.TMP_SUFFIX);
  return { ok: true, message: 'herdr: managed blocks removed, [theme] restored' };
}

module.exports = {
  inspect,
  foreignTables,
  refusal,
  checkedWrite,
  apply,
  remove,
  // Exported for tools/check.js, which reads the poll interval and the timeout
  // back out of the generated text: they are a pair that must not invert.
  block,
  // Also for tools/check.js: every colour this emits has to clear a contrast
  // floor, and the only way to be sure is to read the text that gets written.
  sidebarBlock,
  setSidebarRows,
  applyAppearance,
  chromeVariant,
  blockVariant,
  THEME_START,
  SIDEBAR_START,
};

'use strict';

// One frame of the sidebar, and the memory that carries between frames.
//
// A frame takes a fresh agent-list snapshot (the only source of truth; events
// are wake hints), decides what every pane should display, and writes the
// tokens that changed. What it remembers from frame to frame — which badge is
// held on which pane, what each pane last showed, when each pane last worked —
// lives on the Frame instance. The daemon (lib/daemon.js) owns the clock and
// the scheduler; this module owns the picture.

const herdr = require('./herdr');
const config = require('./config');
const state = require('./state');
const activity = require('./activity');
const view = require('./view');
const lanes = require('./lanes');
const hook = require('./hook');
const { WorkspaceOrder } = require('./workspace-order');
const { logoFor, PULSE_STEPS } = require('./logos');

// One spinner step. The spinner ahead of a working title turns at this rate;
// faster reads as a blur, slower as a stutter. It is also how often the daemon
// wakes while anything works — the price of motion.
// One animation frame. Deliberately equal to the scheduler's POLL_MS
// (lib/daemon.js): our own token writes echo back as pane.updated events, and
// a wake inside the frame floor is refused and re-aimed at lastTick + POLL_MS.
// With any other cadence the animation lands on whichever of the two comes
// later, frame after frame, which is a stutter you can see — 140ms measured
// out as 150, 307, 247, 280.
const SPIN_MS = 150;
// Half a beat of the blocked pulse, in the same units — the mark in front of a
// row waiting on an answer changes this often (lib/logos.js blockedFrame).
const PULSE_MS = SPIN_MS * PULSE_STEPS;
// The longest a frame may sleep with nothing scheduled; watchers and events
// are accelerators, this is the guarantee.
const CATCH_ALL_MS = 30000;
const DONE_HOLD_FOREVER = Number.POSITIVE_INFINITY;
// A tick of the frame counter at minute grain: a working pane then costs one
// sort-key write a minute, and equal minutes compare as strings.
const NO_STAMP = '000000000000';

class Frame {
  constructor(source) {
    this.src = source;

    // Badges and holds.
    this.doneUntil = new Map(); // pane -> when its done badge expires (or forever)
    this.previous = new Map(); // pane -> the status it had last frame
    // Panes that asked something and have not gone back to work since, and
    // whether that pane had ever worked when it asked.
    this.blockedSince = new Map();
    this.blockedHeldWork = new Map();

    // Pane -> when it was last seen `working`. Herdr's screen-pattern
    // detection can misread a redraw gap as `idle` for a second or two
    // mid-turn (observed on macOS; Windows paces differently and does not
    // flap). Without a grace window every blip synthesises a done badge, so
    // the sidebar strobes green/spinner. Loaded rather than empty: the stamps
    // outlive any one daemon.
    this.lastWorkingAt = activity.load();
    // Panes whose missing activity stamp was already looked up once. Sessions
    // older than this plugin have no stamp, but the CLI's own session file
    // does remember them — recover it so they shade honestly instead of all
    // reading as plain idle. The lookup walks directories, so once per pane.
    this.recovered = new Set();

    // What each target last showed, so only changes are written.
    this.lastLine = new Map();
    // pane -> the token map last accepted, so a frame can send only the keys
    // that moved.
    this.lastTokens = new Map();
    this.lastSort = new Map();
    this.lastLogo = new Map();
    this.lastSpace = new Map();
    this.members = ''; // fingerprint of the last group layout written

    // Write-failure backoff, per target. A pane whose writes always fail must
    // not keep the daemon awake retrying every wake — that is a self-inflicted
    // busy loop. Failures back off exponentially to a minute.
    this.failedAt = new Map();
    this.workspaceOrder = new WorkspaceOrder();
  }

  /* ------------------------------------------------------- write backoff */

  writable(key, now) {
    const failure = this.failedAt.get(key);
    return !failure || now >= failure.until;
  }

  settled(key, ok) {
    if (ok) {
      this.failedAt.delete(key);
      return true;
    }
    const failure = this.failedAt.get(key) ?? { count: 0, until: 0 };
    failure.count += 1;
    failure.until = Date.now() + Math.min(60000, 1000 * 2 ** Math.min(failure.count, 6));
    this.failedAt.set(key, failure);
    return false;
  }

  // Persist the activity stamps unconditionally; the daemon calls this on
  // its way out.
  flush() {
    activity.save(this.lastWorkingAt, Date.now(), { force: true });
  }

  /* ------------------------------------------------------------- render */

  // Draw one frame. Returns when the next one is due, or null when the
  // snapshot failed — a failed fetch is not an empty session, and acting on
  // it as one would clear every token and delete every activity stamp.
  async render(now) {
    const entries = await state.snapshot();
    if (entries === null) return null;
    // Labels are always needed: the workspace list drives the Spaces marks.
    const { tabs, workspaces, parents, worktrees } = await state.labels(now);
    // Deadlines this frame discovers; the scheduler sleeps to the earliest.
    const deadlines = [];
    // Every write this frame goes into one parallel batch.
    const jobs = [];

    const keys = this.sortKeys(entries, parents, worktrees);
    await this.workspaceOrder.sync([...workspaces.keys()], keys.wsKeys, parents, now);
    const viewMode = view.mode();
    // Which order the panel is actually displaying. The plugin's own views
    // outrank the config toggle (Herdr disables it while they are active);
    // with neither, the config's grouped/priority choice decides.
    const grouped = viewMode === 'grouped' || (viewMode === null && herdr.panelGrouped(now));
    const displayEntries = this.displayOrder(entries, viewMode, keys);
    // Boundaries are needed now — the per-pane loop indents by them — but the
    // group furniture is WRITTEN after that loop, because a header fades with
    // its workspace and whether a workspace is entirely stale is only known
    // once every one of its panes has a display.
    const heads = grouped ? state.groupBoundaries(displayEntries).heads : new Set();
    // The last pane of each split, in the order the panel will draw them, so
    // the corner under it closes the group instead of continuing it.
    const splitLast = new Map();
    if (grouped) {
      for (const entry of displayEntries) {
        if (keys.splitChild(entry)) splitLast.set(entry.tab, entry.pane);
      }
    }

    const live = new Set();
    // workspace -> the display states of its live agents, for the Spaces marks.
    const wsAgents = new Map();
    const attn = new Map();
    const spinStep = Math.floor(now / SPIN_MS);

    const displays = new Map();
    for (const entry of entries) {
      const display = this.displayFor(entry, now, deadlines);
      displays.set(entry.pane, display);
      attn.set(entry.pane, display === 'blocked' || display === 'done' ? '1' : display === 'working' ? '3' : '2');
    }
    const laneLayout = viewMode === 'attention' ? this.laneLayout(entries, attn, keys) : null;
    for (const entry of entries) {
      live.add(entry.pane);
      const display = displays.get(entry.pane);
      if (entry.workspace) {
        if (!wsAgents.has(entry.workspace)) wsAgents.set(entry.workspace, []);
        wsAgents.get(entry.workspace).push({ display, name: entry.name });
      }
      // Herdr indents an entry's continuation rows for us. A head pane's state
      // line is row 2 and arrives indented already; a member's empty header
      // row collapses, so its state line IS row 1 and the indent has to be
      // ours. That asymmetry is why a worktree needs BOTH branches: give its
      // members the deeper indent without also adding one level for its head,
      // and the head sits a level shallower than the sessions it owns. An
      // orphan indents like a real child: its synthesised parent row puts its
      // own rows one level in, same as a child's explicit corner does. With no
      // headers at all (priority order) every line sits at the margin.
      // Depth: a group's first row sits at the margin, everything below it
      // one level in, a worktree's sessions one further. A split does not add
      // a level — its corner is the offset, and a fourth column of indent on
      // rows that are already the deepest in the list buys nothing.
      const depth = grouped
        ? (heads.has(entry.pane) ? 0 : 1) + (keys.nested(entry.workspace) ? 1 : 0)
        : laneLayout && !laneLayout.heads.has(entry.pane)
          ? 1
          : 0;
      const indent = state.INDENTS[Math.min(depth, state.INDENTS.length - 1)];
      // The other halves of a split screen hang off the pane they were split
      // from, drawn the way a worktree hangs off its checkout.
      const corner = ''; // local patch: no split tree (operator ask 2026-09-27)
      // The header text this row will sit under, for the prefix trim. Empty
      // in the flat view: nothing is repeated there.
    // costs one write a minute, zero-padded so the string sort is the numeric
    // sort. Panes with no stamp publish no $sort_key and sort after every
    // stamped one — Herdr puts missing values last.
    const sortKey = keys.minuteKey(pane);
    const wsKey = entry.workspace ? (keys.wsKeys.get(entry.workspace) ?? null) : null;
    const tabKey = keys.tabKeys.get(pane) ?? null;
    const attnRank = display === 'blocked' || display === 'done' ? '1' : display === 'working' ? '3' : '2';
    const sortPair = `${sortKey}|${wsKey}|${attnRank}`;
    if (this.lastSort.get(pane) !== sortPair && this.writable(`sort:${pane}`, now)) {
      jobs.push(
        herdr
          .reportMetadataAsync(pane, src, { sort_key: sortKey, ws_key: wsKey, tab_key: tabKey, attn_rank: attnRank })
          .then((ok) => {
            if (this.settled(`sort:${pane}`, ok)) this.lastSort.set(pane, sortPair);
          }),
      );
    }

    if (!line) return;

    // A working spinner has to be repainted at the next step, a blocked pulse
    // at the next half of its beat; a timed badge at its expiry. Until-seen
    // badges are static — an event wakes us to clear those.
    const hold = this.doneUntil.get(pane);
    if (display === 'working') deadlines.push((Math.floor(now / SPIN_MS) + 1) * SPIN_MS);
    else if (display === 'blocked') deadlines.push((Math.floor(now / PULSE_MS) + 1) * PULSE_MS);
    else if (hold !== undefined && hold !== DONE_HOLD_FOREVER) deadlines.push(hold);
  }

  // Panes that left the agent list since we last painted them.
  clearGone(live, now, jobs) {
    for (const pane of [...this.lastLine.keys()]) {
      if (live.has(pane)) continue;
      if (!this.writable(`clear:${pane}`, now)) continue;
      jobs.push(
        state.clearState(this.src, pane).then((ok) => {
          if (ok) this.lastTokens.delete(pane);
          if (!this.settled(`clear:${pane}`, ok)) return; // retry after backoff
          // A write that failed before the pane closed has nothing left to
          // retry against; its backoff would only wake the loop for nothing.
          for (const kind of ['line', 'logo', 'sort']) this.failedAt.delete(`${kind}:${pane}`);
          this.lastLine.delete(pane);
          this.lastSort.delete(pane);
          this.lastLogo.delete(pane);
          this.previous.delete(pane);
          this.doneUntil.delete(pane);
          this.lastWorkingAt.delete(pane);
          this.blockedSince.delete(pane);
          this.blockedHeldWork.delete(pane);
        }),
      );
    }
  }

  /* -------------------------------------------------------- Spaces marks */

  // One aggregated glyph per workspace, published as a workspace token.
  // Priority is urgency: a question beats activity beats an unseen result
  // beats parked. The per-pane displays already carry the idle grace and the
  // held done badge, so the aggregate inherits both for free.
  spaceJobs(wsAgents, workspaces, now, jobs) {
    const src = this.src;
    const wsIds = new Set(workspaces.keys());
    for (const ws of wsAgents.keys()) wsIds.add(ws);
    for (const ws of wsIds) {
      const agents = wsAgents.get(ws) ?? [];
      let chosen = 'none';
      let vendor = '';
      for (const p of state.SPACE_PRIORITY) {
        const hit = agents.find((a) => a.display === p);
        if (hit) {
          chosen = p;
          vendor = hit.name;
          break;
        }
      }
      const token = chosen === 'none' ? 'space_none' : state.spaceToken(chosen, vendor);
      const glyph = state.spaceMark(chosen);
      const logos = state.spaceLogoTokens(agents);
      const label = workspaces.get(ws) ?? ws;
      const key = `${token}:${glyph}:${Object.values(logos).join(',')}:${label}`;
      if (this.lastSpace.get(ws) !== key && this.writable(`space:${ws}`, now)) {
        jobs.push(
          state.writeSpaceState(src, ws, token, glyph, logos, label).then((ok) => {
            if (this.settled(`space:${ws}`, ok)) this.lastSpace.set(ws, key);
          }),
        );
      }
    }
    for (const ws of [...this.lastSpace.keys()]) {
      if (wsIds.has(ws)) continue;
      if (!this.writable(`space:${ws}`, now)) continue;
      jobs.push(
        state.clearSpaceState(src, ws).then((ok) => {
          if (this.settled(`space:${ws}`, ok)) this.lastSpace.delete(ws);
        }),
      );
    }
  }

  /* ------------------------------------------------------ group furniture */

  // Headers, indents and spacers, rewritten only when the layout changed. A
  // workspace counts as stale when every session in it is — that is what lets
  // a whole dormant project recede, header included, instead of leaving a row
  // of bright names over faded contents.
  // local patch (2026-09-27): manual groups in the attention view, across machines. The lane
  // token sorts the groups, the first row of each carries its name as the divider and the last
  // row the gap. presence.json says which machine holds those rows, so each box marks only its own.
  laneLayout(entries, attn, keys) {
    const d = lanes.load();
    const sorted = entries
      .map((e) => [e.pane, lanes.laneOf(d, e.pane), lanes.rank(attn.get(e.pane), keys.minuteKey(e.pane))])
      .sort((a, b) => (a[1] !== b[1] ? a[1] - b[1] : a[2] === b[2] ? 0 : a[2] < b[2] ? -1 : 1));
    const mine = {};
    for (const [, lane, r] of sorted) {
      mine[lane] ??= [r, r];
      mine[lane][1] = r;
    }
    const all = lanes.publish(mine);
    const used = new Set(Object.values(all).flatMap((l) => Object.keys(l ?? {}).map(Number)));
    const split = used.size > 1;
    const last = Math.max(...used);
    const layout = sorted.map(([pane, lane], i) => {
      const head = split && sorted[i - 1]?.[1] !== lane && lanes.holds(all, lane, 0);
      const tail = split && lane !== last && sorted[i + 1]?.[1] !== lane && lanes.holds(all, lane, 1);
      return [pane, lanes.token(lane, head), head ? lanes.divider(d.groups[lane]) : null, tail];
    });
    const heads = new Set(layout.filter((l) => l[2] !== null).map((l) => l[0]));
    return { layout, split, heads };
  }

  async laneJobs(entries, layout, now, deadlines) {
    const fingerprint = `attention:${JSON.stringify(layout)}`;
    if (fingerprint === this.members) return;
    const results = await Promise.all(
      layout.map(([pane, lane, group, tail]) =>
        herdr.reportMetadataAsync(pane, this.src, {
          lane,
          group,
          group_parent: null,
          group_stale: null,
          gap: config.groupGap && tail ? '​' : null,
        }),
      ),
    );
    let ok = results.every(Boolean);
    ok = (await state.sweepOrphans(this.src, new Set(entries.map((e) => e.pane)))) && ok;
    if (ok) this.members = fingerprint;
    else deadlines.push(now + 2000);
  }

  async groupJobs(entries, displayEntries, viewMode, grouped, wsAgents, workspaces, keys, now, deadlines) {
    const staleWorkspaces = new Set();
    for (const [ws, agents] of wsAgents) {
      if (agents.length > 0 && agents.every((a) => a.display === 'idle_stale')) staleWorkspaces.add(ws);
    }
    // Headers move when the panes, their displayed order, the mode, or a
    // workspace's collective staleness changes. Topology too: opening or
    // closing a worktree changes the branches drawn and which group holds
    // back its spacer, with the pane list untouched. The labels belong here
    // as well, because a header IS a label: one that arrives after the first
    // write has nothing else to move this and replace the fallback id.
    const fingerprint =
      `${viewMode ?? (grouped ? 'grouped' : 'flat')}:` +
      `${[...staleWorkspaces].sort().join('+')}:` +
      `${[...keys.parentOf]
        .map(([child, parent]) => `${child}<${parent}`)
        .sort()
        .join('+')}:` +
      `${[...keys.orphanRepo]
        .map(([ws, repo]) => `${ws}@${repo}`)
        .sort()
        .join('+')}:` +
      JSON.stringify(displayEntries.map((e) => [e.workspace, e.pane, workspaces.get(e.workspace) ?? e.workspace]));
    if (fingerprint === this.members) return;

    let ok = true;
    if (state.INDENT) {
      const wrote = grouped
        ? await state.writeGroups(this.src, displayEntries, workspaces, staleWorkspaces, {
            parentOf: keys.parentOf,
            orphanRepo: keys.orphanRepo,
          })
        : await state.clearGroups(this.src, entries);
      ok = wrote.ok;
    }
    // Membership changing is exactly when a pane may just have dropped out of
    // the agent list with our tokens still on it.
    ok = (await state.sweepOrphans(this.src, new Set(entries.map((e) => e.pane)))) && ok;
    // Remember this layout only if every write landed; a failed one left a
    // header or spacer on the wrong pane, and only a retry fixes that.
    if (ok) this.members = fingerprint;
    else deadlines.push(now + 2000);
  }
}

module.exports = { Frame, SPIN_MS };
'use strict';

// The resident daemon: one process that owns the sidebar for as long as
// Herdr runs.
//
// A read-only event subscription (lib/subscribe.js) wakes it, a next-deadline
// scheduler sleeps it, and an idle daemon blocked on a pipe costs nothing but
// memory. Events are WAKE HINTS only — every frame's truth is a fresh
// agent-list snapshot (lib/frame.js), which makes replayed, throttled, or
// missed events all equally harmless.
//
// Published tokens are the durable record (a held "done" badge survives the
// daemon), because the daemon can die — and when it does, the watchdog hook
// or the next startup brings a fresh one that reads the tokens back.

const fs = require('node:fs');
const path = require('node:path');

const herdr = require('./herdr');
const config = require('./config');
const state = require('./state');
const view = require('./view');
const logos = require('./logos');
const managed = require('./managed-config');
const subscribe = require('./subscribe');
const control = require('./control');
const tabline = require('./tabline');
const { Frame } = require('./frame');
const { createScheduler } = require('./scheduler');
const { detachedNode } = require('./spawn');
const { stateRoot, ensureDir, herdrConfigPath } = require('./paths');

// A frame may not follow the previous one closer than this: our own token
// writes echo back as pane.updated events, and without a floor the echo of
// frame N schedules frame N+1 early, forever.
const FRAME_FLOOR_MS = 120;
const POLL_MS = 150;
const WAKE_DEBOUNCE_MS = 50;
const TABLINE_MS = 2000;
// How long a title change can sit unnoticed. See the heartbeat below.
const HEARTBEAT_MS = 2000;
const APPEARANCE_MS = 60000;

const ERR_FILE = () => path.join(ensureDir(stateRoot), 'animator.err');

// A resident process must not die silently. The file is truncated at start
// and capped here, so a crash loop cannot fill a disk.
function logError(error) {
  try {
    try {
      if (fs.statSync(ERR_FILE()).size > 256 * 1024) fs.truncateSync(ERR_FILE(), 0);
    } catch {
      // No log yet.
    }
    fs.appendFileSync(ERR_FILE(), `${new Date().toISOString()} ${error?.stack ?? error}\n`, 'utf8');
  } catch {
    // Logging must never take the daemon down.
  }
}

// Run as the daemon. Resolves without doing anything when another daemon
// already owns the control endpoint.
async function start() {
  const src = herdr.source();

  // Log, then exit non-zero so the stderr file and the exit code both say
  // something happened. The watchdog hook or the next startup brings a
  // replacement.
  process.on('uncaughtException', (error) => {
    logError(error);
    process.exit(1);
  });
  process.on('unhandledRejection', (error) => {
    logError(error);
    process.exit(1);
  });

  const frame = new Frame(src);

  // Set by the pipe stop handler: no frame may start once a stop is under way.
  let stopping = false;

  let subscription = null;
  const watchers = [];
  const timers = [];
  let ctl = null;

  const shutdown = (code = 0) => {
    frame.flush();
    subscription?.stop();
    for (const interval of timers) clearInterval(interval);
    for (const watcher of watchers) {
      try {
        watcher.close();
      } catch {
        // Already gone.
      }
    }
    try {
      ctl?.close();
    } catch {
      // Already gone.
    }
    try {
      fs.rmSync(state.LOCK(), { force: true });
      // Consume a stop marker on the way out, whatever triggered the exit. A
      // marker nobody consumed reads as "stop pending" to the next start.
      fs.rmSync(state.STOP(), { force: true });
    } catch {
      // Already gone.
    }
    process.exit(code);
  };

  /* ---------------------------------------------------------- scheduler */

  const tick = async () => {
    if (stopping) return;
    // Wall clock on purpose: the frame compares it with persisted activity
    // stamps. Only the scheduling below is monotonic (lib/scheduler.js).
    const now = Date.now();

    if (fs.existsSync(state.STOP())) return shutdown();

    // The bind is the lock — but on unix a lock that can be taken. A daemon
    // blocked for a moment at startup misses a newcomer's ping, the newcomer
    // takes it for a corpse, unlinks the socket and binds its own, and both go
    // on drawing (lib/control.js serve). The newcomer then writes its pid here.
    //
    // This used to be settled by the pid file alone: another live pid in it
    // meant exit. But a pid reused after a restart is "live" too (#19). So the
    // file is now only the trigger, checked every frame as before, and the
    // endpoint is the judge — whoever answers it is the daemon, and if that is
    // not this process, this process leaves. Frames that find their own pid
    // here cost nothing extra. On Windows a pipe name cannot be taken over, so
    // the endpoint always answers with our own pid there.
    let recorded = null;
    try {
      recorded = Number(fs.readFileSync(state.LOCK(), 'utf8').trim());
    } catch {
      // No file yet.
    }
    if (recorded !== process.pid) {
      if (recorded) {
        const owner = await control.request({ cmd: 'ping' });
        if (owner?.ok && owner.pid !== process.pid) {
          // Its socket file, its pid file, its activity stamps: leave them.
          process.exit(0);
        }
      }
      try {
        fs.writeFileSync(state.LOCK(), String(process.pid), 'utf8');
      } catch {
        // Diagnostics only.
      }
    }

    const sleepUntil = await frame.render(now);
    // A failed snapshot: skip the frame and retry soon. The deadline is a wall
    // clock moment; turn it into a delay now, while `Date.now()` is fresh.
    scheduler.scheduleIn((sleepUntil ?? now + 1000) - Date.now());
  };

  const scheduler = createScheduler({
    floorMs: FRAME_FLOOR_MS,
    pollMs: POLL_MS,
    debounceMs: WAKE_DEBOUNCE_MS,
    run: async () => {
      try {
        await tick();
      } catch (error) {
        logError(error);
        scheduler.scheduleIn(5000);
      }
    },
  });
  const wake = scheduler.wake;

  /* ------------------------------------------------------ control pipe */

      // plugin's look and never rewrite config.toml. Rows go first so the
      // socket call below is the last word — see lib/view.js setRows.
      if (message.op === 'native') view.setRows(Boolean(next));
      const reply = next ? await view.apply(next) : await view.clear();
      if (!reply || reply.error) return { mode: current, applied: false };
      view.setMode(next);
      wake();
      return { mode: next, applied: true };
    },
    stop: async () => {
      // Halt the loop FIRST and wait out any in-flight tick: clearing while a
      // frame is mid-write loses the race — the frame repaints a working pane
      // right over the clear.
      stopping = true;
      while (scheduler.isRunning()) await new Promise((resolve) => setTimeout(resolve, 25));
      await state.clearAll(src);
      // Exit once the reply has left the building.
      setTimeout(() => shutdown(), 50);
      return { stopped: true };
    },
  };
  ctl = await control.serve(handlers);
  // A daemon that was just told to stop may still hold the endpoint for a
  // moment after its reply; a restart (settings popup, `state-stop` then
  // `state-start`) must not lose that race, so retry briefly before deciding
  // a live daemon owns it.
  for (let attempt = 0; !ctl && attempt < 20; attempt += 1) {
    await new Promise((resolve) => setTimeout(resolve, 250));
    ctl = await control.serve(handlers);
  }
  if (!ctl) return; // a live daemon really does own the endpoint

  try {
    fs.writeFileSync(state.LOCK(), String(process.pid), 'utf8');
    fs.rmSync(state.STOP(), { force: true }); // consume a stale stop marker
  } catch {
    // The bind above is the real lock.
  }
  process.on('SIGTERM', () => shutdown());
  process.on('SIGINT', () => shutdown());

  // Put the chosen order on the panel now. The startup hook (agent-view.js
  // --reapply) only runs when Herdr's server starts; a daemon started by hand
  // — the first start after an install — used to leave Herdr's own order in
  // place until the next restart, on a machine whose README promised
  // `active`. Idempotent against the hook: the same override twice is one.
  try {
    const chosen = view.mode();
    if (chosen) await view.apply(chosen);
  } catch (error) {
    logError(error);
  }

  // The sidebar block colours the logo by matching its VALUE against glyph
  // strings, so a block written for the icon font matches nothing once the
  // variant resolves to plain Unicode — the font was installed since, or the
  // setting changed. One file read per start, and a rewrite only when they
  // actually disagree.
  //
  // Only while the block is there. Its ABSENCE is how `agents_panel = herdr`
  // is recorded — nothing else stores that choice — and the variant tag lives
  // inside the block, so a panel handed back to Herdr reads as "no variant",
  // which is not the same as "the wrong one". Rewriting on that reading put
  // our rows back moments after the settings popup removed them: saving the
  // native panel flashed native and returned to the plugin. The appearance
  // switch guards the same trap (managed-config.js applyAppearance).
  try {
    const report = managed.inspect();
    const installed = report.text?.includes(managed.SIDEBAR_START);
    if (installed && managed.blockVariant(report.text) !== logos.resolveVariant()) {
      if (managed.apply().ok) herdr.reloadConfig();
    }
  } catch (error) {
    logError(error);
  }

  // Per-state logo names from before 2.0. A pane last painted by an older
  // version still carries one, and the new block has no cell for it, so it
  // would sit in the row unrendered but reported. Clearing them is a no-op
  // from the second start onwards.
  try {
    await state.sweepOrphans(src, new Set(), state.LEGACY_LOGO_TOKENS);
  } catch (error) {
    logError(error);
  }

  /* ------------------------------------------------------------- wiring */

  subscription = subscribe.start({
    onWake: wake,
    // The server's socket marker is gone: herdr is not coming back on this
    // endpoint. The next herdr start runs the startup hook and spawns a fresh
    // daemon.
    onGone: () => shutdown(),
  });

  // The two state sources that produce no events at all: Herdr's own config
  // (the grouped/priority toggle persists there, via atomic rename — so the
  // DIRECTORY is watched, a watched file dies with the first replacement) and
  // our own signal files (stop marker, view flag). Watchers are an
  // accelerator, not a guarantee — the catch-all deadline covers their loss.
  const watchDir = (dir, names) => {
    try {
      const watcher = fs.watch(dir, (event, file) => {
        if (!file || names.has(String(file))) wake();
      });
      watcher.on('error', () => {});
      watchers.push(watcher);
    } catch {
      // Covered by the catch-all.
    }
  };
  watchDir(path.dirname(herdrConfigPath()), new Set(['config.toml']));
  watchDir(
    ensureDir(stateRoot),
    new Set([path.basename(state.STOP()), 'agent-view.on', 'lanes.json', 'presence.json']),
  );
  // local patch (2026-09-27): the hub keeps groups in step with its peers (bin/lane-sync.js).
  if (require('./lanes').load().peers?.length) {
    const sync = require('node:child_process').spawn(
      process.execPath,
      [path.join(__dirname, '..', 'bin', 'lane-sync.js')],
      { stdio: 'ignore' },
    );
    process.on('exit', () => sync.kill());
  }

  // The tab-bar line is precomputed into a cache file that Herdr's status
  // command merely types out — the daemon pays a couple of socket calls every
  // two seconds instead of Herdr booting a node. The focused pane's cwd
  // changes under us (cd, task switch), so this one genuinely is a poll.
  const refreshTabLine = () =>
    tabline
      .snapshotLine()
      .then((line) => tabline.publish(line))
      .catch(() => {});
  timers.push(setInterval(refreshTabLine, TABLINE_MS));
  refreshTabLine();

  // Terminal titles and working directories change without an event now that
  // `pane.updated` is off (lib/subscribe.js says why). They change rarely, and
  // a frame that finds nothing different writes nothing, so a slow heartbeat
  // is the whole cost of not listening to our own echo.
  timers.push(setInterval(wake, HEARTBEAT_MS));

  // Appearance follow-up. The probe throttles itself to once a minute; sync
  // only rewrites and reloads when the desktop actually flipped.
  //
  // Spawned rather than called in-process, and that is the whole point. That
  // path REWRITES the managed config blocks, and a resident daemon would write
  // them from the module copy it loaded at startup — so an edit to the palette
  // or the row layout would be silently undone by the next desktop flip. A
  // child process always reads the code that is on disk now. It costs one
  // node start per flip, twice a day.
  if (config.followAppearance) {
    timers.push(
      setInterval(() => {
        try {
          detachedNode(path.join(__dirname, '..', 'bin', 'theme-sync.js'));
        } catch (error) {
          logError(error);
        }
      }, APPEARANCE_MS),
    );
  }

  wake();
}

